INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Passwortschutz allein einen USB-Stick vollständig sichert?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung und physische Sicherheit nötig"}, {"text": "Ja", "correct": false, "because": "Unzureichend ohne weitere Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt Daten auf einem mobilen Datenträger vor unbefugtem Zugriff?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Verhindert Lesen ohne Schlüssel"}, {"text": "Komprimierung", "correct": false, "because": "Reduziert Größe, nicht sicher"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen erhöhen die Sicherheit eines mobilen Datenträgers?', 5, '[{"text": "AES-Verschlüsselung", "correct": true, "because": "Starker Datenschutz"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzt Nutzung"}, {"text": "Antivirus-Scans", "correct": true, "because": "Verhindert Malware"}, {"text": "Buntes Design", "correct": false, "because": "Kosmetisch"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein verschlüsselter Datenträger schützt vor Datenlecks. b) Verschlüsselung schützt vor physischem Diebstahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Diebstahl bleibt möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Sicherung eines USB-Sticks?', 4, '[{"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Antivirus-Scans", "correct": false, "because": "Verhindern Malware"}, {"text": "Sticker-Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Passwort allein einen Datenträger schützt?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung zusätzlich nötig"}, {"text": "Ja", "correct": false, "because": "Unzureichend ohne Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren schützt einen Datenträger vor Malware?', 4, '[{"text": "Regelmäßige Scans", "correct": true, "because": "Erkennt Schadsoftware"}, {"text": "Dateikomprimierung", "correct": false, "because": "Kein Schutz"}, {"text": "Manuelles Löschen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Verschlüsselung die Datenleistung eines Datenträgers stark verlangsamt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Moderne Geräte minimieren Einfluss"}, {"text": "Ja", "correct": false, "because": "Leistungseinbußen gering"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt ein physisches Schloss die Daten auf einem Datenträger?', 2, '[{"text": "Nein", "correct": true, "because": "Schützt nur Hardware, nicht Daten"}, {"text": "Ja", "correct": false, "because": "Daten bleiben zugänglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien sichern einen mobilen Datenträger?', 5, '[{"text": "Hardware-Verschlüsselung", "correct": true, "because": "Integrierter Schutz"}, {"text": "Biometrische Sperre", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Farbliche Markierung", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Sicherung eines mobilen Datenträgers?', 4, '[{"text": "Datenverschlüsselung", "correct": true, "because": "Schützt Inhalte"}, {"text": "Schnelle Datenrate", "correct": false, "because": "Sekundär"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Antivirus-Scan schützt vor Malware. b) Er schützt vor Datenverlust durch Diebstahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Diebstahl nicht abgedeckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Datenträger zu sichern?', 3, '[{"text": "Passwortschutz", "correct": false, "because": "Begrenzt Zugriff"}, {"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen USB-Stick vor Datenverlust schütze?', 4, '[{"text": "Verschlüsseln und Backups erstellen", "correct": true, "because": "Schützt und sichert"}, {"text": "Nur Passwort setzen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Schutz nutzen", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein schreibgeschützter Modus alle Probleme löst. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Schützt nicht vor Diebstahl oder Zugriff"}, {"text": "Ja", "correct": false, "because": "Nur eingeschränkter Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip verhindert Datenmanipulation auf einem Datenträger?', 4, '[{"text": "Integritätssicherung", "correct": true, "because": "Erkennt Änderungen"}, {"text": "Dateikomprimierung", "correct": false, "because": "Kein Schutz"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt ein physisches Gehäuse die Daten?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Hardware, nicht Inhalte"}, {"text": "Ja", "correct": false, "because": "Daten bleiben zugänglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein verschlüsselter Datenträger?', 5, '[{"text": "Datenschutz", "correct": true, "because": "Verhindert Fremdzugriff"}, {"text": "Integrität", "correct": true, "because": "Erkennt Manipulation"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Kein Vorteil"}, {"text": "Besseres Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Sicherung eines Datenträgers unwichtig?', 3, '[{"text": "Zugriffskontrolle", "correct": false, "because": "Begrenzt Nutzung"}, {"text": "Malware-Schutz", "correct": false, "because": "Verhindert Infektion"}, {"text": "Verpackungsfarbe", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Datenträger sicher nutzen will?', 4, '[{"text": "Verschlüsseln, scannen, Zugriff schützen", "correct": true, "because": "Umfassender Schutz"}, {"text": "Nur Passwort setzen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Schutz nutzen", "correct": false, "because": "Riskiert Verlust"}]');
